void loadSpriteTitlePalette(void) {
    if (spriteTitle.palette) {
        return;
    }
    const char *error = NULL;
    spriteTitle.palette = playdate->graphics->loadBitmapTable("sprites/sprite-title", &error);
    if (error) {
        playdate->system->error("Unable to load bitmap table of sprite Title: %s", error);
    }
}

